async function findExpensesByUserId(userId, options) {
  return await prisma.expense.findMany({
    where: {
      userId
    },
    include: {
      payments: {
        orderBy: {
          dueDate: "desc"
        },
        take: 1
      },
      paymentCard: true
    },
    orderBy: {
      nextDueDate: options?.orderBy || "asc"
    },
    take: options?.limit
  });
}
async function findExpensesWithFilters(userId, filters) {
  const where = { userId };
  if (filters?.category) {
    where.category = filters.category;
  }
  if (filters?.isRecurring !== undefined) {
    where.isRecurring = filters.isRecurring;
  }
  if (filters?.startDate || filters?.endDate) {
    where.nextDueDate = {};
    if (filters.startDate) {
      where.nextDueDate.gte = filters.startDate;
    }
    if (filters.endDate) {
      where.nextDueDate.lte = filters.endDate;
    }
  }
  return await prisma.expense.findMany({
    where,
    include: {
      payments: {
        orderBy: {
          dueDate: "desc"
        }
      },
      paymentCard: true
    },
    orderBy: {
      nextDueDate: "asc"
    }
  });
}
async function findExpenseById(expenseId) {
  return await prisma.expense.findUnique({
    where: {
      id: expenseId
    },
    include: {
      payments: {
        orderBy: {
          dueDate: "desc"
        }
      },
      paymentCard: true
    }
  });
}
