// ../../packages/core/src/helpers/date.helpers.ts
function isOverdue(date2) {
  if (!date2)
    return false;
  const now = new Date;
  now.setHours(0, 0, 0, 0);
  const compareDate = new Date(date2);
  compareDate.setHours(0, 0, 0, 0);
  return compareDate < now;
}
// ../../packages/core/src/validation/card.validation.ts
function luhnCheck(cardNumber) {
  const digits = cardNumber.replace(/\D/g, "");
  if (digits.length < 13 || digits.length > 19) {
    return false;
  }
  let sum = 0;
  let isEven = false;
  for (let i2 = digits.length - 1;i2 >= 0; i2--) {
    let digit = parseInt(digits[i2], 10);
    if (isEven) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }
    sum += digit;
    isEven = !isEven;
  }
  return sum % 10 === 0;
}
function detectCardBrand(cardNumber) {
  const digits = cardNumber.replace(/\D/g, "");
  if (/^4/.test(digits)) {
    return "Visa";
  }
  if (/^5[1-5]/.test(digits) || /^2(22[1-9]|2[3-9]\d|[3-6]\d{2}|7[01]\d|720)/.test(digits)) {
    return "Mastercard";
  }
  if (/^3[47]/.test(digits)) {
    return "Amex";
  }
  if (/^6011/.test(digits) || /^622(12[6-9]|1[3-9]\d|[2-8]\d{2}|9[01]\d|92[0-5])/.test(digits) || /^64[4-9]/.test(digits) || /^65/.test(digits)) {
    return "Discover";
  }
  return "Unknown";
}
function validateCardNumber(cardNumber) {
  const digits = cardNumber.replace(/\D/g, "");
  if (!digits) {
    return {
      isValid: false,
      brand: "Unknown",
      error: "Card number is required"
    };
  }
  if (digits.length < 13 || digits.length > 19) {
    return {
      isValid: false,
      brand: "Unknown",
      error: "Card number must be 13-19 digits"
    };
  }
  const brand = detectCardBrand(digits);
  const isValid2 = luhnCheck(digits);
  if (!isValid2) {
    return {
      isValid: false,
      brand,
      error: "Invalid card number"
    };
  }
  return {
    isValid: true,
    brand
  };
}
function getLastFourDigits(cardNumber) {
  const digits = cardNumber.replace(/\D/g, "");
  return digits.slice(-4);
}
function validateExpiryDate(month, year2) {
  const currentDate = new Date;
  const currentYear = currentDate.getFullYear();
  const currentMonth = currentDate.getMonth() + 1;
  if (month < 1 || month > 12) {
    return false;
  }
  if (year2 < currentYear) {
    return false;
  }
  if (year2 === currentYear && month < currentMonth) {
    return false;
  }
  if (year2 > currentYear + 10) {
    return false;
  }
  return true;
}
