// ../../packages/core/src/services/currency.ts
async function fetchCurrencyRates(date3) {
  try {
    const targetDate = date3 || new Date().toISOString().split("T")[0];
    const url = `https://nbg.gov.ge/gw/api/ct/monetarypolicy/currencies/ka/json/?date=${targetDate}`;
    const response = await fetch(url);
    if (!response.ok) {
      console.error("Failed to fetch currency rates:", response.statusText);
      return null;
    }
    const data = await response.json();
    return data[0];
  } catch (error) {
    console.error("Error fetching currency rates:", error);
    return null;
  }
}
async function getMainCurrencyRates(date3) {
  const data = await fetchCurrencyRates(date3);
  if (!data) {
    return {
      usd: null,
      eur: null,
      date: null
    };
  }
  const usd = data.currencies.find((c) => c.code === "USD");
  const eur = data.currencies.find((c) => c.code === "EUR");
  return {
    usd: usd || null,
    eur: eur || null,
    date: data.date
  };
}
