// src/utils/notification.ts
async function notifyPastOrOverdueExpense(userId, expenseTitle, dueDate, amount, currency3, paymentId, expenseId) {
  try {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { email: true, name: true }
    });
    if (!user) {
      return { success: false, error: "User not found" };
    }
    const now = new Date;
    now.setHours(0, 0, 0, 0);
    const dueDateNormalized = new Date(dueDate);
    dueDateNormalized.setHours(0, 0, 0, 0);
    const daysUntilDue = Math.ceil((dueDateNormalized.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    if (daysUntilDue > 0) {
      return { success: true };
    }
    let notificationType = "warning";
    let notificationTitle = "New Payment Due Today";
    let messageText = "";
    if (daysUntilDue < 0) {
      const daysOverdue = Math.abs(daysUntilDue);
      notificationType = "error";
      notificationTitle = "New Overdue Payment Added";
      messageText = `${expenseTitle} was due ${daysOverdue} ${daysOverdue === 1 ? "day" : "days"} ago`;
    } else {
      messageText = `${expenseTitle} is due today`;
    }
    await prisma.notification.create({
      data: {
        userId,
        title: notificationTitle,
        message: messageText,
        type: notificationType,
        actionUrl: "/expenses",
        metadata: JSON.stringify({
          paymentId,
          expenseId,
          dueDate,
          amount,
          isOverdue: daysUntilDue < 0,
          daysUntilDue,
          isNewExpense: true
        })
      }
    });
    const emailResult = await sendPaymentReminderEmail({
      email: user.email,
      userName: user.name || undefined,
      expenseTitle,
      amount,
      currency: currency3,
      dueDate,
      daysUntilDue
    });
    if (!emailResult.success) {
      console.error(`Failed to send email for new overdue expense: ${emailResult.error}`);
    }
    return { success: true };
  } catch (error) {
    console.error("Error in notifyPastOrOverdueExpense:", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error"
    };
  }
}

// src/routes/expense.routes.ts
function serializeExpense(expense) {
  return {
    ...expense,
    amount: Number(expense.amount),
    payments: expense.payments.map((p) => ({
      ...p,
      amount: Number(p.amount)
    }))
  };
}
var expenseRoutes = new Elysia({ prefix: "/expenses", name: "routes/expenses" }).use(authMiddleware).get("/", async ({ userId, query }) => {
  const page = Math.max(1, query.page ?? 1);
  const pageSize = Math.min(100, Math.max(1, query.pageSize ?? EXPENSES_PER_PAGE));
  const filters = {};
  if (query.category)
    filters.category = query.category;
  if (query.isRecurring !== undefined)
    filters.isRecurring = query.isRecurring;
  if (query.startDate)
    filters.startDate = new Date(query.startDate);
  if (query.endDate)
    filters.endDate = new Date(query.endDate);
  const allExpenses = await findExpensesWithFilters(userId, filters);
  const total = allExpenses.length;
  const start = (page - 1) * pageSize;
  const paginatedExpenses = allExpenses.slice(start, start + pageSize);
  return ok({
    data: paginatedExpenses.map(serializeExpense),
    total,
    page,
    pageSize,
    totalPages: Math.ceil(total / pageSize)
  });
}, {
  query: t.Object({
    category: t.Optional(t.String()),
    isRecurring: t.Optional(t.Boolean()),
    startDate: t.Optional(t.String()),
    endDate: t.Optional(t.String()),
    page: t.Optional(t.Number({ minimum: 1 })),
    pageSize: t.Optional(t.Number({ minimum: 1, maximum: 100 }))
  }),
  detail: {
    tags: ["Expenses"],
    summary: "List expenses with filters and pagination",
    description: "Returns paginated expenses for the authenticated user. Supports filtering by category, recurring status, and date range.",
    security: [{ bearerAuth: [] }]
  }
}).get("/:id", async ({ userId, params, set }) => {
  const expense = await findExpenseById(params.id);
  if (!expense || expense.userId !== userId) {
    set.status = 404;
    return fail("Expense not found", ERROR_CODES.NOT_FOUND);
  }
  return ok(serializeExpense(expense));
}, {
  params: t.Object({ id: t.String({ format: "uuid" }) }),
  detail: {
    tags: ["Expenses"],
    summary: "Get a single expense with payments",
    security: [{ bearerAuth: [] }]
  }
}).post("/", async ({ userId, body, set }) => {
  const expenseData = {
    userId,
    title: body.title.trim(),
    amount: body.amount,
    currency: body.currency || "GEL",
    description: body.description?.trim() || null,
    category: body.category?.trim() || null,
    isRecurring: body.isRecurring || false,
    recurrenceRule: body.recurrenceRule || null,
    startDate: body.startDate ? new Date(body.startDate) : null,
    nextDueDate: body.nextDueDate ? new Date(body.nextDueDate) : null,
    paymentCardId: body.paymentCardId || null
  };
  if (body.paymentCardId) {
    const card2 = await prisma.paymentCard.findFirst({
      where: { id: body.paymentCardId, userId }
    });
    if (!card2) {
      set.status = 404;
      return fail("Payment card not found", ERROR_CODES.NOT_FOUND);
    }
  }
  const expense = await prisma.expense.create({
    data: expenseData,
    include: {
      payments: true,
      paymentCard: true
    }
  });
  if (body.nextDueDate) {
    const newPayment = await prisma.payment.create({
      data: {
        expenseId: expense.id,
        dueDate: new Date(body.nextDueDate),
        amount: body.amount
      }
    });
    const dueDate = new Date(body.nextDueDate);
    const now = new Date;
    now.setHours(0, 0, 0, 0);
    const dueDateNorm = new Date(dueDate);
    dueDateNorm.setHours(0, 0, 0, 0);
    if (dueDateNorm <= now) {
      await notifyPastOrOverdueExpense(userId, body.title.trim(), dueDate, body.amount, body.currency || "GEL", newPayment.id, expense.id);
    }
  }
  const created = await findExpenseById(expense.id);
  set.status = 201;
  return ok(serializeExpense(created));
}, {
  body: t.Object({
    title: t.String({ minLength: 1, maxLength: 255 }),
    amount: t.Number({ minimum: 0.01, maximum: 999999999.99 }),
    currency: t.Optional(t.Union([t.Literal("GEL"), t.Literal("USD"), t.Literal("EUR")])),
    description: t.Optional(t.String({ maxLength: 1000 })),
    category: t.Optional(t.String({ maxLength: 100 })),
    isRecurring: t.Optional(t.Boolean()),
    recurrenceRule: t.Optional(t.String({ maxLength: 255 })),
    startDate: t.Optional(t.String({ format: "date-time" })),
    nextDueDate: t.Optional(t.String({ format: "date-time" })),
    paymentCardId: t.Optional(t.String({ format: "uuid" }))
  }),
  detail: {
    tags: ["Expenses"],
    summary: "Create a new expense",
    description: "Creates an expense and optionally an initial payment. If nextDueDate is past or today, an overdue notification is sent.",
    security: [{ bearerAuth: [] }]
  }
}).patch("/:id", async ({ userId, params, body, set }) => {
  const existing = await prisma.expense.findFirst({
    where: { id: params.id, userId }
  });
  if (!existing) {
    set.status = 404;
    return fail("Expense not found", ERROR_CODES.NOT_FOUND);
  }
  if (body.paymentCardId) {
    const card2 = await prisma.paymentCard.findFirst({
      where: { id: body.paymentCardId, userId }
    });
    if (!card2) {
      set.status = 404;
      return fail("Payment card not found", ERROR_CODES.NOT_FOUND);
    }
  }
  const updateData = {};
  if (body.title !== undefined)
    updateData.title = body.title.trim();
  if (body.amount !== undefined)
    updateData.amount = body.amount;
  if (body.currency !== undefined)
    updateData.currency = body.currency;
  if (body.description !== undefined)
    updateData.description = body.description.trim() || null;
  if (body.category !== undefined)
    updateData.category = body.category.trim() || null;
  if (body.isRecurring !== undefined)
    updateData.isRecurring = body.isRecurring;
  if (body.recurrenceRule !== undefined)
    updateData.recurrenceRule = body.recurrenceRule || null;
  if (body.startDate !== undefined)
    updateData.startDate = body.startDate ? new Date(body.startDate) : null;
  if (body.nextDueDate !== undefined)
    updateData.nextDueDate = body.nextDueDate ? new Date(body.nextDueDate) : null;
  if (body.paymentCardId !== undefined)
    updateData.paymentCardId = body.paymentCardId || null;
  await prisma.expense.update({
    where: { id: params.id },
    data: updateData
  });
  const updated = await findExpenseById(params.id);
  return ok(serializeExpense(updated));
}, {
  params: t.Object({ id: t.String({ format: "uuid" }) }),
  body: t.Object({
    title: t.Optional(t.String({ minLength: 1, maxLength: 255 })),
    amount: t.Optional(t.Number({ minimum: 0.01, maximum: 999999999.99 })),
    currency: t.Optional(t.Union([t.Literal("GEL"), t.Literal("USD"), t.Literal("EUR")])),
    description: t.Optional(t.String({ maxLength: 1000 })),
    category: t.Optional(t.String({ maxLength: 100 })),
    isRecurring: t.Optional(t.Boolean()),
    recurrenceRule: t.Optional(t.String({ maxLength: 255 })),
    startDate: t.Optional(t.Nullable(t.String({ format: "date-time" }))),
    nextDueDate: t.Optional(t.Nullable(t.String({ format: "date-time" }))),
    paymentCardId: t.Optional(t.Nullable(t.String({ format: "uuid" })))
  }),
  detail: {
    tags: ["Expenses"],
    summary: "Update an expense",
    security: [{ bearerAuth: [] }]
  }
}).delete("/:id", async ({ userId, params, set }) => {
  const expense = await prisma.expense.findFirst({
    where: { id: params.id, userId }
  });
  if (!expense) {
    set.status = 404;
    return fail("Expense not found", ERROR_CODES.NOT_FOUND);
  }
  await prisma.expense.delete({ where: { id: params.id } });
  set.status = 204;
}, {
  params: t.Object({ id: t.String({ format: "uuid" }) }),
  detail: {
    tags: ["Expenses"],
    summary: "Delete an expense",
    security: [{ bearerAuth: [] }]
  }
}).post("/:id/mark-paid", async ({ userId, params, set }) => {
  const expense = await prisma.expense.findFirst({
    where: { id: params.id, userId },
    include: {
      payments: {
        where: { paid: false },
        orderBy: { dueDate: "asc" },
        take: 1
      }
    }
  });
  if (!expense) {
    set.status = 404;
    return fail("Expense not found", ERROR_CODES.NOT_FOUND);
  }
  if (expense.payments.length === 0) {
    set.status = 422;
    return fail("No unpaid payments found for this expense", ERROR_CODES.VALIDATION_ERROR);
  }
  const payment = expense.payments[0];
  await prisma.payment.update({
    where: { id: payment.id },
    data: { paid: true, paidAt: new Date }
  });
  const updated = await findExpenseById(params.id);
  return ok(serializeExpense(updated));
}, {
  params: t.Object({ id: t.String({ format: "uuid" }) }),
  detail: {
    tags: ["Expenses"],
    summary: "Mark earliest unpaid payment as paid",
    description: "Finds the earliest unpaid payment for this expense and marks it as paid with the current timestamp.",
    security: [{ bearerAuth: [] }]
  }
});

// src/routes/dashboard.routes.ts
var dashboardRoutes = new Elysia({ prefix: "/dashboard", name: "routes/dashboard" }).use(authMiddleware).get("/", async ({ userId }) => {
  const allExpenses = await findExpensesByUserId(userId);
  const now = new Date;
  now.setHours(0, 0, 0, 0);
  const thirtyDaysFromNow = new Date(now);
  thirtyDaysFromNow.setDate(now.getDate() + 30);
  const expenseItems = allExpenses.map((e) => {
    const latestPayment = e.payments[0] || null;
    const isPaid = latestPayment?.paid ?? false;
    const expenseIsOverdue = !isPaid && isOverdue(e.nextDueDate);
    return {
      id: e.id,
      title: e.title,
      amount: Number(e.amount),
      currency: e.currency,
      category: e.category,
      nextDueDate: e.nextDueDate,
      isOverdue: expenseIsOverdue,
      isPaid,
      isRecurring: e.isRecurring,
      paymentCard: e.paymentCard ? {
        id: e.paymentCard.id,
        nickname: e.paymentCard.nickname,
        lastFourDigits: e.paymentCard.lastFourDigits,
        cardBrand: e.paymentCard.cardBrand,
        color: e.paymentCard.color
      } : null
    };
  });
  const stats = {
    total: 0,
    paid: 0,
    pending: 0,
    overdue: 0,
    count: expenseItems.length
  };
  for (const item of expenseItems) {
    stats.total += item.amount;
    if (item.isPaid) {
      stats.paid += item.amount;
    } else if (item.isOverdue) {
      stats.overdue += item.amount;
    } else {
      stats.pending += item.amount;
    }
  }
  stats.total = Math.round(stats.total * 100) / 100;
  stats.paid = Math.round(stats.paid * 100) / 100;
  stats.pending = Math.round(stats.pending * 100) / 100;
  stats.overdue = Math.round(stats.overdue * 100) / 100;
  const recentExpenses = expenseItems.slice(0, DASHBOARD_RECENT_LIMIT);
  const upcomingExpenses = expenseItems.filter((e) => {
    if (e.isPaid || e.isOverdue || !e.nextDueDate)
      return false;
    const due = new Date(e.nextDueDate);
    return due >= now && due <= thirtyDaysFromNow;
  }).slice(0, 5);
  const categoryMap = new Map;
  for (const item of expenseItems) {
    const cat = item.category || "Uncategorized";
    const existing = categoryMap.get(cat) || { amount: 0, count: 0 };
    existing.amount += item.amount;
    existing.count += 1;
    categoryMap.set(cat, existing);
  }
  const categoryData = Array.from(categoryMap.entries()).map(([category, data]) => ({
    category,
    amount: Math.round(data.amount * 100) / 100,
    count: data.count
  })).sort((a12, b) => b.amount - a12.amount);
  return ok({
    expenses: recentExpenses,
    stats,
    upcomingExpenses,
    categoryData
  });
}, {
  detail: {
    tags: ["Dashboard"],
    summary: "Get dashboard data (stats, recent expenses, upcoming, categories)",
    description: "Returns aggregated statistics (total, paid, pending, overdue amounts), recent expenses, upcoming expenses (next 30 days), and category breakdown.",
    security: [{ bearerAuth: [] }]
  }
});

// src/index.ts
var PORT = parseInt(process.env.API_PORT || "4000", 10);
var app = new Elysia().use(cors_plugin_default).use(rateLimitMiddleware()).use(jwt_plugin_default).use(bearer()).use(swagger_plugin_default).onError(({ code, error, set }) => {
  switch (code) {
    case "VALIDATION":
      set.status = 422;
      return fail(error.message, ERROR_CODES.VALIDATION_ERROR);
    case "NOT_FOUND":
      set.status = 404;
      return fail("Route not found", ERROR_CODES.NOT_FOUND);
    case "PARSE":
      set.status = 400;
      return fail("Invalid request body", ERROR_CODES.VALIDATION_ERROR);
    default:
      console.error("Unhandled error:", error);
      set.status = 500;
      return fail("Internal server error", ERROR_CODES.INTERNAL_ERROR);
  }
}).get("/health", () => ({ status: "ok" }), {
  detail: { tags: ["Health"], summary: "Health check" }
}).use(authRoutes).use(currencyRoutes).use(settingsRoutes).use(categoryRoutes).use(paymentCardRoutes).use(notificationRoutes).use(expenseRoutes).use(dashboardRoutes).listen({ port: PORT, hostname: "0.0.0.0" });
console.log(`ExtraTracker API running on http://0.0.0.0:${PORT}`);
